import type { Extension } from '@codemirror/state';
import { EditorView, keymap } from '@codemirror/view';

export function singleLine(): Extension {
  return [
    keymap.of([
      {
        key: 'Enter',
        run: () => true,
      },
    ]),
    EditorView.inputHandler.of((view, from, to, text) => {
      if (text.includes('\n') || text.includes('\r')) {
        view.dispatch({
          changes: { from, to, insert: text.replace(/[\n\r]/g, '') },
        });
        return true;
      }

      return false;
    }),
    EditorView.domEventHandlers({
      wheel(event) {
        // Prevent vertical wheel/trackpad from causing horizontal scroll
        if (Math.abs(event.deltaY) > Math.abs(event.deltaX)) {
          event.preventDefault();
          return true;
        }
        return false;
      },
    }),
    EditorView.theme({
      '&': {
        height: '100%',
      },
      '.cm-scroller': {
        overflow: 'hidden !important',
        scrollbarWidth: 'none',
      },
      '.cm-scroller::-webkit-scrollbar': {
        display: 'none',
      },
      '.cm-content': {
        whiteSpace: 'nowrap',
      },
      '.cm-line': {
        padding: '0',
      },
    }),
  ];
}

import {
  completionStatus,
  selectedCompletion,
  type CompletionContext,
  type CompletionResult,
} from '@codemirror/autocomplete';
import { type Extension, StateEffect, StateField, type Text } from '@codemirror/state';
import {
  Decoration,
  type DecorationSet,
  EditorView,
  hoverTooltip,
  type Tooltip,
  ViewPlugin,
  type ViewUpdate,
  WidgetType,
} from '@codemirror/view';

import {
  getVariableMatches,
  getCompletionMatch,
  type Variable,
  type VariableMatchOptions,
} from '../../components/editor-variables.js';

export function createVariableDecorations(
  doc: Text,
  resolver?: (name: string) => string | undefined,
  options?: VariableMatchOptions,
): DecorationSet {
  const decorations: { from: number; to: number; decoration: Decoration }[] = [];
  const text = doc.toString();

  for (const match of getVariableMatches(text, options)) {
    const resolved = resolver?.(match.name);

    decorations.push({
      from: match.from,
      to: match.to,
      decoration: Decoration.mark({
        class: resolved !== undefined ? 'cm-variable cm-variable-resolved' : 'cm-variable',
        attributes: { 'data-variable': match.name },
      }),
    });
  }

  return Decoration.set(
    decorations.map((decoration) => decoration.decoration.range(decoration.from, decoration.to)),
    true,
  );
}

export const setResolverEffect = StateEffect.define<(name: string) => string | undefined>();

export const resolverField = StateField.define<((name: string) => string | undefined) | undefined>({
  create: () => undefined,
  update: (value, transaction) => {
    for (const effect of transaction.effects) {
      if (effect.is(setResolverEffect)) {
        return effect.value;
      }
    }
    return value;
  },
});

export function variableHighlighting(
  resolver?: (name: string) => string | undefined,
  options?: VariableMatchOptions,
): Extension {
  return [
    resolverField.init(() => resolver),
    ViewPlugin.fromClass(
      class {
        decorations: DecorationSet;

        constructor(view: EditorView) {
          const nextResolver = view.state.field(resolverField, false);
          this.decorations = createVariableDecorations(view.state.doc, nextResolver, options);
        }

        update(update: ViewUpdate) {
          if (
            update.docChanged ||
            update.transactions.some((transaction) =>
              transaction.effects.some((effect) => effect.is(setResolverEffect)),
            )
          ) {
            const nextResolver = update.state.field(resolverField, false);
            this.decorations = createVariableDecorations(update.state.doc, nextResolver, options);
          }
        }
      },
      { decorations: (view) => view.decorations },
    ),
  ];
}

export function variableCompletions(
  variables: readonly Variable[],
  options?: VariableMatchOptions,
) {
  return (context: CompletionContext): CompletionResult | null => {
    const beforeCursor = context.state.sliceDoc(Math.max(0, context.pos - 50), context.pos);
    const completionMatch = getCompletionMatch(beforeCursor, options);

    if (!completionMatch) {
      return null;
    }

    const typed = completionMatch.typedSegment.trim() || '';
    const from = context.pos - typed.length;
    const filtered = variables.filter((variable) =>
      variable.name.toLowerCase().startsWith(typed.toLowerCase()),
    );

    if (filtered.length === 0) {
      return null;
    }

    return {
      from,
      options: filtered.map((variable) => ({
        label: variable.name,
        type: 'variable',
        ...(variable.value !== undefined ? { detail: variable.value } : {}),
        ...(variable.description !== undefined ? { info: variable.description } : {}),
        apply(view, completion, applyFrom, applyTo) {
          const textAfter = view.state.sliceDoc(
            applyTo,
            applyTo + completionMatch.template.close.length + 6,
          );
          const hasClosing = textAfter.trim().startsWith(completionMatch.template.close);
          let insert = completion.label;

          if (!hasClosing) {
            insert += completionMatch.template.close;
          }

          view.dispatch({
            changes: { from: applyFrom, to: applyTo, insert },
            selection: { anchor: applyFrom + insert.length },
          });
        },
      })),
    };
  };
}

// ---------------------------------------------------------------------------
// Inline ghost preview (IntelliJ / Copilot style)
// ---------------------------------------------------------------------------

class GhostCompletionWidget extends WidgetType {
  constructor(private readonly text: string) {
    super();
  }

  eq(other: GhostCompletionWidget) {
    return other.text === this.text;
  }

  toDOM() {
    const span = document.createElement('span');
    span.className = 'cm-completion-ghost';
    span.textContent = this.text;
    return span;
  }

  ignoreEvent() {
    return true;
  }
}

/**
 * Renders the currently-selected completion inline as dimmed ghost text right
 * after the cursor (accept with Tab, arrow keys still pick another from the
 * dropdown). Purely visual — the actual insert is done by the completion's
 * `apply`, so this only previews the same result.
 */
export function inlineCompletionPreview(options?: VariableMatchOptions): Extension {
  return ViewPlugin.fromClass(
    class {
      decorations: DecorationSet = Decoration.none;

      constructor(view: EditorView) {
        this.decorations = this.build(view);
      }

      update(update: ViewUpdate) {
        this.decorations = this.build(update.view);
      }

      build(view: EditorView): DecorationSet {
        const { state } = view;
        if (completionStatus(state) !== 'active') {
          return Decoration.none;
        }
        const selected = selectedCompletion(state);
        if (!selected) {
          return Decoration.none;
        }

        const cursor = state.selection.main.head;
        if (!state.selection.main.empty) {
          return Decoration.none;
        }

        const before = state.sliceDoc(Math.max(0, cursor - 50), cursor);
        const match = getCompletionMatch(before, options);
        if (!match) {
          return Decoration.none;
        }

        const typed = match.typedSegment.trim();
        const label = selected.label;
        if (!label.toLowerCase().startsWith(typed.toLowerCase())) {
          return Decoration.none;
        }

        let ghost = label.slice(typed.length);
        const after = state.sliceDoc(cursor, cursor + match.template.close.length);
        if (!after.startsWith(match.template.close)) {
          ghost += match.template.close;
        }
        if (!ghost) {
          return Decoration.none;
        }

        return Decoration.set([
          Decoration.widget({
            widget: new GhostCompletionWidget(ghost),
            side: 1,
          }).range(cursor),
        ]);
      }
    },
    { decorations: (plugin) => plugin.decorations },
  );
}

export function variableHoverTooltip(options?: VariableMatchOptions): Extension {
  return hoverTooltip((view, pos) => {
    const resolver = view.state.field(resolverField, false);
    const text = view.state.doc.toString();

    for (const match of getVariableMatches(text, options)) {
      if (pos >= match.from && pos < match.to) {
        const resolved = resolver?.(match.name);

        return {
          pos: match.from,
          end: match.to,
          above: true,
          create(): { dom: HTMLElement } {
            const dom = document.createElement('div');
            dom.className = 'cm-variable-tooltip';

            const nameElement = document.createElement('div');
            nameElement.className = 'cm-variable-tooltip-name';
            nameElement.textContent = match.name;
            dom.appendChild(nameElement);

            const valueElement = document.createElement('div');
            valueElement.className =
              resolved !== undefined
                ? 'cm-variable-tooltip-value'
                : 'cm-variable-tooltip-value cm-variable-tooltip-unresolved';

            if (resolved === undefined) {
              valueElement.textContent = 'Not defined';
            } else if (resolved === '') {
              valueElement.textContent = '(Empty string)';
              valueElement.classList.add('cm-variable-tooltip-empty');
            } else {
              valueElement.textContent = resolved;
            }

            dom.appendChild(valueElement);

            return { dom };
          },
        } satisfies Tooltip;
      }
    }

    return null;
  });
}

'use client';

import { createContext, useContext, type ReactNode } from 'react';
import { createPortal } from 'react-dom';

/** Undefined means standalone; null means a frame's host has not mounted yet. */
export const GraphAnnotationContext = createContext<HTMLDivElement | null | undefined>(undefined);

/** An attached annotation stays outside the card's clipped visual surface. */
export function GraphAnnotationPortal({ children }: { children: ReactNode }) {
  const host = useContext(GraphAnnotationContext);
  if (host === undefined) return children;
  return host ? createPortal(children, host) : null;
}

import { useLayoutEffect } from 'react';

import {
  getBezierPath,
  Position,
  useStore,
  type ConnectionLineComponentProps,
} from '@xyflow/react';

import { graphAnchorSideFromHandle as anchorSideFromHandle } from '../../blocks/graph-types.js';
import { getConnectionLineStart } from './geometry.js';
import { useGraphGestureStore } from './context.js';
import type { EngineNode } from './model.js';

/**
 * The line drawn while a connection is in flight.
 *
 * Both ends preview the result. The anchored end starts where the finished
 * edge will start: on the grabbed border's midpoint for a new connection, on
 * the retained end's pinned border for a reconnect, and facing the pointer
 * when that end floats. The far end rides the raw pointer — React Flow's own
 * `to` snaps to the centre of whatever handle the pointer is over, and the
 * whole-node drop target makes that snap a teleport to the node's centre.
 */
/**
 * Which way the line arrives at the pointer.
 *
 * The pointer has no border to meet, so this end used to be pinned to `Top`.
 * A bezier pulls its control point out of the side it is given, so the line
 * always reached up and over before it came back down — drag left or down and
 * it hooked against the direction of travel. Facing the way the drag is going
 * makes it read as one line the pointer is pulling.
 */
function getPointerSide(from: { x: number; y: number }, to: { x: number; y: number }): Position {
  const dx = to.x - from.x;
  const dy = to.y - from.y;

  if (Math.abs(dx) >= Math.abs(dy)) {
    return dx > 0 ? Position.Left : Position.Right;
  }

  return dy > 0 ? Position.Top : Position.Bottom;
}

export function GraphConnectionLine({
  toX,
  toY,
  fromNode,
  fromHandle,
  pointer,
}: ConnectionLineComponentProps<EngineNode>) {
  // `pointer` is container-relative; the transform maps it into flow space.
  const { recordConnectionLine, getReconnectRetained } = useGraphGestureStore();
  const [translateX, translateY, zoom] = useStore((state) => state.transform);
  const endX = pointer ? (pointer.x - translateX) / zoom : toX;
  const endY = pointer ? (pointer.y - translateY) / zoom : toY;

  // A reconnect wins outright, including when the retained end has no pin: its
  // record is the only honest source. React Flow's own `fromHandle` is a
  // fallback it picked, not the border this edge actually meets.
  const retained = getReconnectRetained();
  const pinnedSide = retained ? retained.side : anchorSideFromHandle(fromHandle?.id);
  const start = getConnectionLineStart(fromNode, { x: endX, y: endY }, pinnedSide);

  const sourceX = start?.x ?? endX;
  const sourceY = start?.y ?? endY;
  const sourcePosition = start?.position ?? Position.Bottom;
  const targetPosition = getPointerSide({ x: sourceX, y: sourceY }, { x: endX, y: endY });

  // In an effect, not the render body. Recording is a side effect, and React
  // may render this component without committing it — a discarded render would
  // otherwise publish a position that never reached the screen, and the settle
  // would travel from somewhere the line never was.
  useLayoutEffect(() => {
    recordConnectionLine({
      fromX: sourceX,
      fromY: sourceY,
      fromPosition: sourcePosition,
      toX: endX,
      toY: endY,
      toPosition: targetPosition,
    });
  }, [sourceX, sourceY, sourcePosition, endX, endY, targetPosition, recordConnectionLine]);

  const [path] = getBezierPath({
    sourceX,
    sourceY,
    sourcePosition,
    targetX: endX,
    targetY: endY,
    targetPosition,
    curvature: 0.2,
  });

  return (
    <g>
      <path
        d={path}
        fill="none"
        className="ns-graph-connection-path"
        strokeWidth={2}
        strokeDasharray="6 6"
      />
      <circle cx={endX} cy={endY} r={4} className="ns-graph-connection-pointer" strokeWidth={2} />
    </g>
  );
}

import { createContext, useContext, useState, type ReactNode } from 'react';
import { createGraphGestureStore } from './gesture.js';

const GestureContext = createContext<ReturnType<typeof createGraphGestureStore> | null>(null);

export function GraphGestureProvider({ children }: { children: ReactNode }) {
  const [store] = useState(createGraphGestureStore);
  return <GestureContext.Provider value={store}>{children}</GestureContext.Provider>;
}

export function useGraphGestureStore() {
  const store = useContext(GestureContext);
  if (!store) throw new Error('Graph gesture components must be inside GraphCanvas.');
  return store;
}

import type { CSSProperties } from 'react';

import { useLayoutEffect, useRef } from 'react';

import {
  BaseEdge,
  EdgeLabelRenderer,
  getBezierPath,
  Position,
  useInternalNode,
  type EdgeProps,
} from '@xyflow/react';

import { getFloatingEdgeParams, getPinnedCurvature } from './geometry.js';
import { useGraphEdgePresentation } from './presentation.js';
import type { EngineEdge } from './model.js';
import { lerpEdgePath, useEdgeSettle } from './use-edge-settle.js';

/**
 * How far a reconnect anchor sits back from the border it meets.
 *
 * An endpoint lands on the node's border, and the border carries the 12px
 * connect band. Nodes render above edges, so an anchor left on the endpoint is
 * covered by that band and the pointer never reaches it — the drag starts a new
 * connection instead of moving the end of this one. Standing the anchor off the
 * border clears the band and keeps it on the line.
 */
const ANCHOR_STANDOFF = 14;

/**
 * The target anchor stands off further, because that end carries the arrowhead.
 *
 * The head is 9px long, measured back from the border. At the shared standoff
 * the dot's near edge landed 1px from the head's tail, so the two read as one
 * smeared blob. Clearing the head plus the dot's own radius puts a real gap
 * between them: 9 for the head, 4 for the radius, 5 of air.
 */
const TARGET_ANCHOR_STANDOFF = 18;

/** Unit vector pointing away from the node, out of the border it meets. */
const awayFromNode: Record<Position, { x: number; y: number }> = {
  [Position.Left]: { x: -1, y: 0 },
  [Position.Right]: { x: 1, y: 0 },
  [Position.Top]: { x: 0, y: -1 },
  [Position.Bottom]: { x: 0, y: 1 },
};

/** The head sits on the border it arrives at, pointing into the node. */
const arrowRotationByTargetSide: Record<Position, number> = {
  [Position.Left]: 0,
  [Position.Right]: 180,
  [Position.Top]: 90,
  [Position.Bottom]: 270,
};

export function GraphEdgeRenderer({
  id,
  source,
  target,
  data: engineData,
  selected,
  sourceX,
  sourceY,
  sourcePosition,
  targetX,
  targetY,
  targetPosition,
}: EdgeProps<EngineEdge>) {
  const data = engineData?.model;
  const presentation = useGraphEdgePresentation(id);
  // Endpoints come from the two nodes' geometry, not from a handle, so the edge
  // meets whichever border faces the other node. The props are the fallback for
  // the frame before React Flow has measured them.
  const floating = getFloatingEdgeParams(useInternalNode(source), useInternalNode(target), {
    source: data?.sourceAnchor,
    target: data?.targetAnchor,
  });
  const geometry = floating ?? {
    sourceX,
    sourceY,
    sourcePosition,
    targetX,
    targetY,
    targetPosition,
  };
  const tone = presentation?.tone ?? data?.tone ?? 'neutral';
  const phase = presentation?.phase;
  const travelMs = Number.isFinite(presentation?.travelMs)
    ? Math.max(0, Math.min(presentation!.travelMs!, 60_000))
    : 340;
  const shouldAnimate = data?.motion === 'flow';
  const dashDuration = tone === 'danger' ? '1s' : '1.5s';

  const [finalPath, finalLabelX, finalLabelY] = getBezierPath({
    ...geometry,
    curvature: getPinnedCurvature(geometry, 0.2),
  });

  // A just-released connection travels from where its line was to where the
  // edge resolved, instead of teleporting there in one frame.
  const { originGeometry, progress } = useEdgeSettle(id, geometry, {
    source: data?.sourceAnchor,
    target: data?.targetAnchor,
  });

  let path = finalPath;
  let labelX = finalLabelX;
  let labelY = finalLabelY;
  let drawnTargetX = geometry.targetX;
  let drawnTargetY = geometry.targetY;

  if (originGeometry) {
    const [originPath, originLabelX, originLabelY] = getBezierPath({
      ...originGeometry,
      curvature: getPinnedCurvature(originGeometry, 0.2),
    });
    path = lerpEdgePath(originPath, finalPath, progress) ?? finalPath;
    labelX = originLabelX + (finalLabelX - originLabelX) * progress;
    labelY = originLabelY + (finalLabelY - originLabelY) * progress;
    drawnTargetX = originGeometry.targetX + (geometry.targetX - originGeometry.targetX) * progress;
    drawnTargetY = originGeometry.targetY + (geometry.targetY - originGeometry.targetY) * progress;
  }

  /**
   * React Flow draws the two reconnect anchors from the handle it resolved for
   * the edge, and a floating edge ends wherever its geometry says. The two
   * disagree, so the anchors sat on the node tops while the edge ran between
   * two side borders — the grab point was never on the line.
   *
   * The anchors are siblings of this component inside the edge's own `<g>`, so
   * move them onto the real endpoints. Everything else about reconnect —
   * validity, the `connectingto` state, `onReconnect` — keeps working, because
   * the drag reads the pointer, not the circle.
   *
   * Their radius stays untouched: it is the hit area, and the visible dot is
   * drawn separately below. Sizing the circle itself would shrink the target
   * to whatever the dot looks like.
   */
  const anchorRef = useRef<SVGGElement>(null);

  // Two short edges would put the pair on top of each other, so the standoff
  // never eats more than a third of the run.
  const span = Math.hypot(geometry.targetX - geometry.sourceX, geometry.targetY - geometry.sourceY);
  const sourceStandoff = Math.min(ANCHOR_STANDOFF, span / 3);
  const targetStandoff = Math.min(TARGET_ANCHOR_STANDOFF, span / 3);

  const sourceStep = awayFromNode[geometry.sourcePosition];
  const targetStep = awayFromNode[geometry.targetPosition];

  const anchors = {
    sourceX: geometry.sourceX + sourceStep.x * sourceStandoff,
    sourceY: geometry.sourceY + sourceStep.y * sourceStandoff,
    targetX: geometry.targetX + targetStep.x * targetStandoff,
    targetY: geometry.targetY + targetStep.y * targetStandoff,
  };

  useLayoutEffect(() => {
    const group = anchorRef.current?.parentElement;
    if (!group) {
      return;
    }

    const place = (selector: string, x: number, y: number) => {
      const anchor = group.querySelector(selector);
      if (anchor) {
        anchor.setAttribute('cx', String(x));
        anchor.setAttribute('cy', String(y));
      }
    };

    place('.react-flow__edgeupdater-source', anchors.sourceX, anchors.sourceY);
    place('.react-flow__edgeupdater-target', anchors.targetX, anchors.targetY);
  }, [anchors.sourceX, anchors.sourceY, anchors.targetX, anchors.targetY]);

  return (
    <g
      ref={anchorRef}
      data-tone={tone}
      data-selected={selected}
      data-ns-settling={progress < 1}
      data-ns-phase={phase}
      data-ns-pattern={data?.pattern ?? 'solid'}
      data-ns-instant={presentation?.instant || undefined}
      style={presentation ? ({ '--ns-edge-travel': `${travelMs}ms` } as CSSProperties) : undefined}
    >
      {/* A selected edge used to differ by 0.75px of stroke width, which reads
          as nothing. The halo is the selection: it traces the same path, wide
          and faint, under the edge itself. */}
      {selected ? (
        <path
          d={path}
          fill="none"
          strokeWidth={10}
          strokeLinecap="round"
          className="ns-graph-edge-halo"
        />
      ) : null}

      <BaseEdge
        id={id}
        path={path}
        interactionWidth={28}
        data-ns-phase={phase}
        className={
          shouldAnimate ? 'ns-graph-edge-path ns-graph-edge-animated' : 'ns-graph-edge-path'
        }
        style={
          {
            ...(shouldAnimate ? { strokeDasharray: '12, 12' } : {}),
            ...(shouldAnimate ? { '--flow-edge-dash-duration': dashDuration } : {}),
          } as CSSProperties
        }
      />

      {phase ? (
        <>
          <path d={path} pathLength={1} className="ns-graph-edge-progress" data-ns-phase={phase} />
          {phase === 'traversed' && !presentation?.instant ? (
            <path d={path} pathLength={1} className="ns-graph-edge-comet" data-ns-phase={phase} />
          ) : null}
        </>
      ) : null}

      <polygon
        points="0,-4.5 9,0 0,4.5"
        className="ns-graph-edge-arrow"
        transform={`translate(${drawnTargetX} ${drawnTargetY}) rotate(${arrowRotationByTargetSide[geometry.targetPosition]}) translate(-9 0)`}
      />

      {data?.label ? (
        <EdgeLabelRenderer>
          <div
            className="ns-graph-edge-label-position"
            style={{
              transform: `translate(-50%, -50%) translate(${labelX}px, ${labelY}px)`,
            }}
          >
            <span className="ns-graph-edge-label" data-tone={tone}>
              {data.label}
            </span>
          </div>
        </EdgeLabelRenderer>
      ) : null}

      {/* What the user aims at. Inert, because React Flow's own anchor sits at
          the same point and carries the full grab radius. */}
      <circle className="ns-graph-edge-anchor" cx={anchors.sourceX} cy={anchors.sourceY} r={4} />
      <circle className="ns-graph-edge-anchor" cx={anchors.targetX} cy={anchors.targetY} r={4} />
    </g>
  );
}

import { Position, type InternalNode, type Node } from '@xyflow/react';

/**
 * Where an edge meets a node.
 *
 * Nodes have no fixed anchors any more, so an edge cannot ask a handle where to
 * start. It works the endpoint out from geometry instead: the point where the
 * line between the two node centres crosses the node's own border. Move either
 * node and the edge slides around the border to keep facing the other one.
 */

type Measured = { width: number; height: number };

function getMeasured(node: InternalNode<Node>): Measured | null {
  const width = node.measured?.width;
  const height = node.measured?.height;

  if (!width || !height) {
    return null;
  }

  return { width, height };
}

function getCentre(node: InternalNode<Node>, measured: Measured) {
  return {
    x: node.internals.positionAbsolute.x + measured.width / 2,
    y: node.internals.positionAbsolute.y + measured.height / 2,
  };
}

/**
 * The point on `node`'s border that faces `other`.
 *
 * Solves the rectangle-line intersection in the node's own normalised space,
 * which is why the two halves are divided out before the sum is scaled back.
 * Same approach as React Flow's floating-edges example.
 */
function getBorderPoint(
  node: InternalNode<Node>,
  nodeMeasured: Measured,
  other: InternalNode<Node>,
  otherMeasured: Measured,
) {
  const halfWidth = nodeMeasured.width / 2;
  const halfHeight = nodeMeasured.height / 2;
  const centre = getCentre(node, nodeMeasured);
  const otherCentre = getCentre(other, otherMeasured);

  const dx = (otherCentre.x - centre.x) / (2 * halfWidth);
  const dy = (otherCentre.y - centre.y) / (2 * halfHeight);

  const u = dx - dy;
  const v = dx + dy;
  const scale = 1 / (Math.abs(u) + Math.abs(v) || 1);

  return {
    x: halfWidth * (scale * u + scale * v) + centre.x,
    y: halfHeight * (-scale * u + scale * v) + centre.y,
  };
}

/** Which border the point landed on, so the bezier leaves at a sane angle. */
function getBorderSide(
  node: InternalNode<Node>,
  measured: Measured,
  point: { x: number; y: number },
): Position {
  const left = Math.round(node.internals.positionAbsolute.x);
  const top = Math.round(node.internals.positionAbsolute.y);
  const x = Math.round(point.x);
  const y = Math.round(point.y);

  if (x <= left + 1) {
    return Position.Left;
  }
  if (x >= left + measured.width - 1) {
    return Position.Right;
  }
  if (y <= top + 1) {
    return Position.Top;
  }

  return Position.Bottom;
}

/**
 * A pinned attachment. Absent means the endpoint floats and keeps facing the
 * other node; set means the user chose that border and it stays there.
 */
import type { EdgeAnchorSide } from '../../blocks/graph-types.js';
export type { EdgeAnchorSide };

const ANCHOR_POSITIONS: Record<EdgeAnchorSide, Position> = {
  top: Position.Top,
  right: Position.Right,
  bottom: Position.Bottom,
  left: Position.Left,
};

export function isEdgeAnchorSide(value: unknown): value is EdgeAnchorSide {
  return value === 'top' || value === 'right' || value === 'bottom' || value === 'left';
}

/** The midpoint of a pinned border. */
function getAnchorPoint(node: InternalNode<Node>, measured: Measured, side: EdgeAnchorSide) {
  const { x, y } = node.internals.positionAbsolute;

  switch (side) {
    case 'top':
      return { x: x + measured.width / 2, y };
    case 'bottom':
      return { x: x + measured.width / 2, y: y + measured.height };
    case 'left':
      return { x, y: y + measured.height / 2 };
    case 'right':
      return { x: x + measured.width, y: y + measured.height / 2 };
  }
}

export type FloatingEdgeParams = {
  sourceX: number;
  sourceY: number;
  targetX: number;
  targetY: number;
  sourcePosition: Position;
  targetPosition: Position;
};

/**
 * Returns `null` until React Flow has measured both nodes. The edge falls back
 * to the handle-based coordinates for that first frame rather than drawing a
 * line through the origin.
 */
export function getFloatingEdgeParams(
  source: InternalNode<Node> | undefined,
  target: InternalNode<Node> | undefined,
  anchors?: { source?: EdgeAnchorSide | undefined; target?: EdgeAnchorSide | undefined },
): FloatingEdgeParams | null {
  if (!source || !target) {
    return null;
  }

  const sourceMeasured = getMeasured(source);
  const targetMeasured = getMeasured(target);

  if (!sourceMeasured || !targetMeasured) {
    return null;
  }

  // A pinned side wins over the facing-border solve. That is the whole point of
  // pinning: the edge stays where it was put, even when moving a node would
  // otherwise swing it to another border.
  const sourcePoint = anchors?.source
    ? getAnchorPoint(source, sourceMeasured, anchors.source)
    : getBorderPoint(source, sourceMeasured, target, targetMeasured);
  const targetPoint = anchors?.target
    ? getAnchorPoint(target, targetMeasured, anchors.target)
    : getBorderPoint(target, targetMeasured, source, sourceMeasured);

  return {
    sourceX: sourcePoint.x,
    sourceY: sourcePoint.y,
    targetX: targetPoint.x,
    targetY: targetPoint.y,
    sourcePosition: anchors?.source
      ? ANCHOR_POSITIONS[anchors.source]
      : getBorderSide(source, sourceMeasured, sourcePoint),
    targetPosition: anchors?.target
      ? ANCHOR_POSITIONS[anchors.target]
      : getBorderSide(target, targetMeasured, targetPoint),
  };
}

/**
 * The bezier for an edge, with a capped hook on a pinned end that faces away
 * from the other one.
 *
 * React Flow's `getBezierPath` pulls each control point out of the side it is
 * given, and its opposing-side offset grows without bound
 * (`curvature * 25 * sqrt(distance)`). Pin the left border and connect to a
 * node on the right, and the control point sat 97px out the back — the curve
 * left the node the wrong way and swept round in an S. The aligned case is
 * unchanged. The opposing case keeps a short stub, so the edge still exits
 * perpendicular from the pinned border and then turns.
 */
const OPPOSING_CONTROL_STUB = 24;

function getControlOffset(distance: number, curvature: number): number {
  if (distance >= 0) {
    return 0.5 * distance;
  }

  return Math.min(curvature * 25 * Math.sqrt(-distance), OPPOSING_CONTROL_STUB);
}

function getControlPoint(
  position: Position,
  x: number,
  y: number,
  otherX: number,
  otherY: number,
  curvature: number,
): { x: number; y: number } {
  switch (position) {
    case Position.Left:
      return { x: x - getControlOffset(x - otherX, curvature), y };
    case Position.Right:
      return { x: x + getControlOffset(otherX - x, curvature), y };
    case Position.Top:
      return { x, y: y - getControlOffset(y - otherY, curvature) };
    case Position.Bottom:
      return { x, y: y + getControlOffset(otherY - y, curvature) };
  }
}

/** Same shape as `getBezierPath`: the path and the label point. */
export function getFlowEdgePath(
  params: FloatingEdgeParams & { curvature?: number },
): [string, number, number] {
  const curvature = params.curvature ?? 0.2;
  const sourceControl = getControlPoint(
    params.sourcePosition,
    params.sourceX,
    params.sourceY,
    params.targetX,
    params.targetY,
    curvature,
  );
  const targetControl = getControlPoint(
    params.targetPosition,
    params.targetX,
    params.targetY,
    params.sourceX,
    params.sourceY,
    curvature,
  );

  // The cubic at t = 0.5, the same label point React Flow uses.
  const labelX =
    params.sourceX * 0.125 +
    sourceControl.x * 0.375 +
    targetControl.x * 0.375 +
    params.targetX * 0.125;
  const labelY =
    params.sourceY * 0.125 +
    sourceControl.y * 0.375 +
    targetControl.y * 0.375 +
    params.targetY * 0.125;

  return [
    `M${params.sourceX},${params.sourceY} C${sourceControl.x},${sourceControl.y} ${targetControl.x},${targetControl.y} ${params.targetX},${params.targetY}`,
    labelX,
    labelY,
  ];
}

/**
 * The in-progress connection line: where it leaves the node it is anchored to.
 *
 * With a pinned side it starts at that border's midpoint, which is exactly
 * where the finished edge will start — the drag previews the result. Without
 * one it leaves the border facing the pointer, the way a floating endpoint
 * will.
 */
export function getConnectionLineStart(
  source: InternalNode<Node> | undefined,
  pointer: { x: number; y: number },
  pinnedSide?: EdgeAnchorSide,
): { x: number; y: number; position: Position } | null {
  const measured = source ? getMeasured(source) : null;

  if (!source || !measured) {
    return null;
  }

  if (pinnedSide) {
    return {
      ...getAnchorPoint(source, measured, pinnedSide),
      position: ANCHOR_POSITIONS[pinnedSide],
    };
  }

  const pointerAsNode = {
    measured: { width: 1, height: 1 },
    internals: { positionAbsolute: pointer },
  } as InternalNode<Node>;

  const point = getBorderPoint(source, measured, pointerAsNode, {
    width: 1,
    height: 1,
  });

  return { ...point, position: getBorderSide(source, measured, point) };
}

/**
 * The border of `node` closest to `point`.
 *
 * A release on the node body has to pin somewhere, and the border the pointer
 * came nearest is the one the user was reaching for. Distance is measured to
 * each of the four edges of the node, so a release near a corner picks the side
 * it is truly closer to rather than a fixed preference.
 */
export function getNearestBorderSide(
  node: InternalNode<Node> | undefined,
  point: { x: number; y: number },
): EdgeAnchorSide | undefined {
  const measured = node ? getMeasured(node) : null;

  if (!node || !measured) {
    return undefined;
  }

  const left = node.internals.positionAbsolute.x;
  const top = node.internals.positionAbsolute.y;

  const distances: Record<EdgeAnchorSide, number> = {
    left: Math.abs(point.x - left),
    right: Math.abs(left + measured.width - point.x),
    top: Math.abs(point.y - top),
    bottom: Math.abs(top + measured.height - point.y),
  };

  return (Object.keys(distances) as EdgeAnchorSide[]).reduce((nearest, side) =>
    distances[side] < distances[nearest] ? side : nearest,
  );
}

/** Unit vector pointing out of the border an endpoint meets. */
const BORDER_NORMALS: Record<Position, { x: number; y: number }> = {
  [Position.Left]: { x: -1, y: 0 },
  [Position.Right]: { x: 1, y: 0 },
  [Position.Top]: { x: 0, y: -1 },
  [Position.Bottom]: { x: 0, y: 1 },
};

/**
 * How much curve an edge earns, given the borders it is pinned to.
 *
 * A bezier pushes its control point straight out of the side it is given. When
 * that side faces away from the other node the line leaves backwards before it
 * turns around: grabbing the left band of a node whose target is to the right
 * sent the start 112px the wrong way and bowed the path 29px off straight.
 *
 * A pinned edge must still leave its border, so the answer is a shorter stub,
 * not a straight line. An end that already faces the other node keeps the full
 * curve, so every arrangement that looked right still does.
 */
export function getPinnedCurvature(geometry: FloatingEdgeParams, base: number): number {
  const dx = geometry.targetX - geometry.sourceX;
  const dy = geometry.targetY - geometry.sourceY;
  const span = Math.hypot(dx, dy);

  if (span === 0) {
    return base;
  }

  const toTarget = { x: dx / span, y: dy / span };
  const sourceNormal = BORDER_NORMALS[geometry.sourcePosition];
  const targetNormal = BORDER_NORMALS[geometry.targetPosition];

  // Positive means the border faces the way the edge travels.
  const sourceFacing = sourceNormal.x * toTarget.x + sourceNormal.y * toTarget.y;
  const targetFacing = targetNormal.x * -toTarget.x + targetNormal.y * -toTarget.y;
  const worst = Math.min(sourceFacing, targetFacing);

  if (worst >= 0) {
    return base;
  }

  return base * (0.15 + 0.85 * ((worst + 1) / 2));
}

import type { Position } from '@xyflow/react';

import type { EdgeAnchorSide } from './geometry.js';

/**
 * Transient state of the connection gesture in flight.
 *
 * Three parties need it and none of them can reach the others. The connection
 * line knows where it drew, the canvas knows which edge a release produced,
 * and the edge that appears wants to travel from the line's last position
 * instead of teleporting to its resolved geometry. React Flow clears its
 * connection state before `onConnect` runs, so this module carries the
 * hand-off. Every read is gated on freshness — stale state cannot leak into
 * an unrelated mount.
 */

export type ConnectionLineSnapshot = {
  fromX: number;
  fromY: number;
  fromPosition: Position;
  toX: number;
  toY: number;
  toPosition: Position;
};

const SETTLE_MAX_AGE_MS = 400;

export function createGraphGestureStore() {
  let lineSnapshot: (ConnectionLineSnapshot & { at: number }) | null = null;
  let armedEdge: { id: string; at: number } | null = null;

  function recordConnectionLine(snapshot: ConnectionLineSnapshot): void {
    lineSnapshot = { ...snapshot, at: performance.now() };
  }

  /** Marks `edgeId` as the edge the release is about to produce. */
  function armConnectionSettle(edgeId: string): void {
    armedEdge = { id: edgeId, at: performance.now() };
  }

  /**
   * The line geometry to settle from, if `edgeId` is the edge the gesture just
   * produced. Freshness does the cleanup: the snapshot is not consumed, so a
   * StrictMode double mount settles the same edge twice instead of losing the
   * animation.
   */
  function takeConnectionSettle(edgeId: string): ConnectionLineSnapshot | null {
    const now = performance.now();

    if (!armedEdge || armedEdge.id !== edgeId) {
      return null;
    }
    if (now - armedEdge.at > SETTLE_MAX_AGE_MS) {
      return null;
    }
    if (!lineSnapshot || now - lineSnapshot.at > SETTLE_MAX_AGE_MS) {
      return null;
    }

    return lineSnapshot;
  }

  /**
   * The end that stays put while the other end of an edge is dragged.
   *
   * `null` means no reconnect is in flight. A record whose `side` is undefined
   * means a reconnect IS in flight and that end carries no pin, so it should
   * float and keep facing the pointer. The two cases must stay distinct: React
   * Flow resolves the retained end from `edge.sourceHandle`/`targetHandle`, which
   * this canvas never sets, so it falls back to the node's first handle — a top
   * one. Reading the side off that handle swings the far end to the top of its
   * node the moment an endpoint is picked up.
   */
  let retained: { side: EdgeAnchorSide | undefined } | null = null;

  function recordReconnectRetainedAnchor(side: EdgeAnchorSide | undefined): void {
    retained = { side };
  }

  function clearReconnectRetainedAnchor(): void {
    retained = null;
  }

  function getReconnectRetained(): {
    side: EdgeAnchorSide | undefined;
  } | null {
    return retained;
  }

  return {
    recordConnectionLine,
    armConnectionSettle,
    takeConnectionSettle,
    recordReconnectRetainedAnchor,
    clearReconnectRetainedAnchor,
    getReconnectRetained,
  };
}

import type { Edge, Node } from '@xyflow/react';
import type { GraphEdge, GraphNode } from '../../blocks/graph-types.js';

export type EngineNode = Node<{ model: GraphNode }, 'block'>;
export type EngineEdge = Edge<{ model: GraphEdge }, 'graph'>;

/** Copy only supported data. A JavaScript object cannot smuggle engine styling props. */
export function toEngineNode(model: GraphNode): EngineNode {
  return {
    id: model.id,
    type: 'block',
    position: { x: model.position.x, y: model.position.y },
    data: { model },
    ...(model.selected === undefined ? {} : { selected: model.selected }),
    ...(model.measured === undefined ? {} : { measured: model.measured }),
    ...(model.hidden === undefined ? {} : { hidden: model.hidden }),
    ...(model.draggable === undefined ? {} : { draggable: model.draggable }),
    ...(model.connectable === undefined ? {} : { connectable: model.connectable }),
    ...(model.selectable === undefined ? {} : { selectable: model.selectable }),
    ...(model.deletable === undefined ? {} : { deletable: model.deletable }),
    ...(model.ariaLabel === undefined ? {} : { ariaLabel: model.ariaLabel }),
  };
}

export function toEngineEdge(model: GraphEdge): EngineEdge {
  return {
    id: model.id,
    type: 'graph',
    source: model.source,
    target: model.target,
    data: { model },
    ...(model.selected === undefined ? {} : { selected: model.selected }),
    ...(model.hidden === undefined ? {} : { hidden: model.hidden }),
    ...(model.deletable === undefined ? {} : { deletable: model.deletable }),
  };
}

export function fromEngineNode(node: EngineNode): GraphNode {
  return {
    ...node.data.model,
    position: node.position,
    ...(node.selected === undefined ? {} : { selected: node.selected }),
    ...(node.dragging === undefined ? {} : { dragging: node.dragging }),
    ...(node.measured === undefined ? {} : { measured: node.measured }),
  };
}

export function fromEngineEdge(edge: EngineEdge): GraphEdge {
  if (!edge.data) throw new Error('Graph edge data is missing.');
  return {
    ...edge.data.model,
    ...(edge.selected === undefined ? {} : { selected: edge.selected }),
  };
}

'use client';

import { useLayoutEffect, useRef } from 'react';
import { Handle, Position, useConnection, type NodeProps } from '@xyflow/react';
import { GraphNodeFrame } from '../../blocks/graph-node.js';
import { useGraphNodePresentation } from './presentation.js';
import type { EngineNode } from './model.js';

const borders = [Position.Top, Position.Right, Position.Bottom, Position.Left];

function ConnectionSurface({ id, connectable }: { id: string; connectable: boolean }) {
  const connecting = useConnection((connection) => connection.inProgress);
  return (
    <>
      <span aria-hidden="true" className="ns-graph-connect-ring" />
      {borders.map((side) => (
        <Handle
          key={side}
          id={`band-${side}-${id}`}
          type="source"
          position={side}
          isConnectable={connectable}
          className="ns-graph-connect-band"
          data-side={side}
          data-inert={connecting || !connectable}
        />
      ))}
      <Handle
        id={`node-${id}`}
        type="target"
        position={Position.Top}
        isConnectable={connectable}
        className="ns-graph-drop-surface"
        data-inert={!connecting || !connectable}
      />
      {borders.map((side) => (
        <Handle
          key={`drop-${side}`}
          id={`drop-${side}-${id}`}
          type="target"
          position={side}
          isConnectable={connectable}
          className="ns-graph-connect-band"
          data-side={side}
          data-inert={!connecting || !connectable}
        />
      ))}
    </>
  );
}

export function GraphNodeRenderer({ id, data, selected, isConnectable }: NodeProps<EngineNode>) {
  const { model } = data;
  const presentation = useGraphNodePresentation(id);
  const content = useRef<HTMLDivElement>(null);
  // The engine reads its no-drag marker before React's delegated handlers.
  // Register controls centrally, including controls mounted by disclosures.
  useLayoutEffect(() => {
    const element = content.current;
    if (!element) return;
    const markControls = () => {
      element
        .querySelectorAll(
          'button, a, input, select, textarea, [contenteditable="true"], [role="button"], [role="checkbox"], [role="combobox"]',
        )
        .forEach((control) => control.classList.add('nodrag'));
    };
    markControls();
    const observer = new MutationObserver(markControls);
    observer.observe(element, { childList: true, subtree: true });
    return () => observer.disconnect();
  }, []);
  return (
    <div ref={content} className="ns-graph-node">
      <GraphNodeFrame
        tone={presentation?.tone ?? model.tone ?? 'neutral'}
        width={model.width ?? 'standard'}
        family={model.family ?? 'call'}
        phase={presentation?.phase ?? model.phase ?? 'idle'}
        instant={presentation?.instant ?? model.instant ?? false}
        selected={selected}
        emphasis={presentation?.emphasis ?? model.emphasis ?? 'normal'}
      >
        {model.content}
      </GraphNodeFrame>
      <ConnectionSurface id={id} connectable={isConnectable} />
    </div>
  );
}

import { createContext, useCallback, useContext, useSyncExternalStore } from 'react';
import type { GraphPresentationStore } from '../../blocks/graph-types.js';

export const GraphPresentationContext = createContext<GraphPresentationStore | undefined>(
  undefined,
);
const subscribeIdle = () => () => {};

export function useGraphNodePresentation(id: string) {
  const store = useContext(GraphPresentationContext);
  return useSyncExternalStore(
    store?.subscribe ?? subscribeIdle,
    useCallback(() => store?.getNodeSnapshot(id), [store, id]),
    useCallback(() => store?.getServerNodeSnapshot?.(id), [store, id]),
  );
}
export function useGraphEdgePresentation(id: string) {
  const store = useContext(GraphPresentationContext);
  return useSyncExternalStore(
    store?.subscribe ?? subscribeIdle,
    useCallback(() => store?.getEdgeSnapshot(id), [store, id]),
    useCallback(() => store?.getServerEdgeSnapshot?.(id), [store, id]),
  );
}

/** Keep these geometry and motion choices aligned with styles/dock.css. */
export const INSPECTOR_WIDTH = 416;
export const SHEET_SHARE = 0.6;
export const INSPECTOR_DURATION = 260;

function shortestMove(start: number, end: number, available: number) {
  const min = 24;
  const max = Math.max(min, available - 24);
  if (end - start > max - min || start < min) return min - start;
  return end > max ? max - end : 0;
}

/** Reveal an item with minimal movement; oversized items keep their start readable. */
export function revealOffset(
  rect: { left: number; top: number; right: number; bottom: number },
  width: number,
  height: number,
) {
  return {
    dx: shortestMove(rect.left, rect.right, width),
    dy: shortestMove(rect.top, rect.bottom, height),
  };
}

/** Evaluate the inspector's CSS cubic-bezier(0.32, 0.72, 0, 1). */
export function inspectorEase(progress: number) {
  if (progress <= 0 || progress >= 1) return Math.max(0, Math.min(1, progress));
  const sample = (t: number, a: number, b: number) =>
    3 * (1 - t) ** 2 * t * a + 3 * (1 - t) * t ** 2 * b + t ** 3;
  let low = 0;
  let high = 1;
  for (let i = 0; i < 20; i += 1) {
    const middle = (low + high) / 2;
    if (sample(middle, 0.32, 0) < progress) low = middle;
    else high = middle;
  }
  return sample((low + high) / 2, 0.72, 1);
}

import { useEffect, useLayoutEffect, useRef, useState } from 'react';

import type { ConnectionLineSnapshot } from './gesture.js';
import { useGraphGestureStore } from './context.js';
import type { EdgeAnchorSide, FloatingEdgeParams } from './geometry.js';

/**
 * Travels a just-drawn edge from where the connection line last was to where
 * the edge resolved. Without it the endpoint jumps from the release point to
 * the pinned border's midpoint in a single frame — an SVG path `d` cannot be
 * CSS-transitioned, so the travel has to be computed.
 *
 * It arms on mount and whenever the edge's pinned anchors change, which
 * covers a new connection, a reconnect onto another node (new edge id), and a
 * reconnect onto another border of the same node (same id, new anchor). The
 * gesture store only answers for the edge the release actually produced, so
 * every other mount renders its resolved geometry straight away.
 */

const SETTLE_DURATION_MS = 160;
/** Shortened, not removed: the snap is the thing the travel exists to prevent. */
const SETTLE_REDUCED_MOTION_DURATION_MS = 120;

/** The `--ease-out` token, cubic-bezier(0.23, 1, 0.32, 1), evaluated in JS. */
const EASE_OUT_X1 = 0.23;
const EASE_OUT_Y1 = 1;
const EASE_OUT_X2 = 0.32;
const EASE_OUT_Y2 = 1;

function sampleCurve(t: number, p1: number, p2: number): number {
  const inverse = 1 - t;
  return 3 * inverse * inverse * t * p1 + 3 * inverse * t * t * p2 + t * t * t;
}

function sampleDerivative(t: number, p1: number, p2: number): number {
  const inverse = 1 - t;
  return 3 * inverse * inverse * p1 + 6 * inverse * t * (p2 - p1) + 3 * t * t * (1 - p2);
}

function easeOut(x: number): number {
  if (x <= 0) {
    return 0;
  }
  if (x >= 1) {
    return 1;
  }

  let t = x;
  for (let iteration = 0; iteration < 5; iteration += 1) {
    const slope = sampleDerivative(t, EASE_OUT_X1, EASE_OUT_X2);
    if (slope === 0) {
      break;
    }
    t -= (sampleCurve(t, EASE_OUT_X1, EASE_OUT_X2) - x) / slope;
  }

  return sampleCurve(t, EASE_OUT_Y1, EASE_OUT_Y2);
}

type SettleState = {
  origin: ConnectionLineSnapshot;
  swapEnds: boolean;
  startedAt: number;
  duration: number;
};

function distance(ax: number, ay: number, bx: number, by: number): number {
  return Math.hypot(bx - ax, by - ay);
}

export function useEdgeSettle(
  edgeId: string,
  geometry: FloatingEdgeParams,
  anchors: { source?: EdgeAnchorSide | undefined; target?: EdgeAnchorSide | undefined },
): { originGeometry: FloatingEdgeParams | null; progress: number } {
  const { takeConnectionSettle } = useGraphGestureStore();
  const anchorKey = `${anchors.source ?? ''}:${anchors.target ?? ''}`;
  const [settle, setSettle] = useState<SettleState | null>(null);
  const [progress, setProgress] = useState(1);

  const geometryRef = useRef(geometry);
  const lastAnchorKey = useRef<string | null>(null);

  // Declared before the anchor effect, so the ref is fresh when it reads it.
  useLayoutEffect(() => {
    geometryRef.current = geometry;
  });

  useLayoutEffect(() => {
    if (lastAnchorKey.current === anchorKey) {
      return;
    }
    lastAnchorKey.current = anchorKey;

    const origin = takeConnectionSettle(edgeId);
    if (!origin) {
      return;
    }

    // A source-end reconnect draws its line from the retained target, so the
    // snapshot's ends can arrive swapped. The pairing with the shorter total
    // travel is the right one.
    const current = geometryRef.current;
    const straight =
      distance(origin.fromX, origin.fromY, current.sourceX, current.sourceY) +
      distance(origin.toX, origin.toY, current.targetX, current.targetY);
    const swapped =
      distance(origin.fromX, origin.fromY, current.targetX, current.targetY) +
      distance(origin.toX, origin.toY, current.sourceX, current.sourceY);

    setSettle({
      origin,
      swapEnds: swapped < straight,
      startedAt: performance.now(),
      duration: window.matchMedia('(prefers-reduced-motion: reduce)').matches
        ? SETTLE_REDUCED_MOTION_DURATION_MS
        : SETTLE_DURATION_MS,
    });
    setProgress(0);
  }, [anchorKey, edgeId, takeConnectionSettle]);

  useEffect(() => {
    if (!settle) {
      return;
    }

    let frame: number;
    const tick = () => {
      const elapsed = performance.now() - settle.startedAt;
      if (elapsed >= settle.duration) {
        setProgress(1);
        setSettle(null);
        return;
      }
      setProgress(easeOut(elapsed / settle.duration));
      frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);

    return () => cancelAnimationFrame(frame);
  }, [settle]);

  if (!settle || progress >= 1) {
    return { originGeometry: null, progress: 1 };
  }

  const { origin, swapEnds } = settle;
  const originGeometry: FloatingEdgeParams = swapEnds
    ? {
        sourceX: origin.toX,
        sourceY: origin.toY,
        sourcePosition: origin.toPosition,
        targetX: origin.fromX,
        targetY: origin.fromY,
        targetPosition: origin.fromPosition,
      }
    : {
        sourceX: origin.fromX,
        sourceY: origin.fromY,
        sourcePosition: origin.fromPosition,
        targetX: origin.toX,
        targetY: origin.toY,
        targetPosition: origin.toPosition,
      };

  return { originGeometry, progress };
}

const PATH_NUMBER_PATTERN = /-?\d+(?:\.\d+)?(?:e[+-]?\d+)?/gi;

/**
 * Interpolates two paths from `getBezierPath` number by number. Both come
 * from the same generator, so the shapes always align; `null` says they did
 * not, and the caller falls back to the finished path.
 */
export function lerpEdgePath(from: string, to: string, progress: number): string | null {
  const fromNumbers = from.match(PATH_NUMBER_PATTERN);
  const toNumbers = to.match(PATH_NUMBER_PATTERN);

  if (!fromNumbers || !toNumbers || fromNumbers.length !== toNumbers.length) {
    return null;
  }

  let index = 0;
  return to.replace(PATH_NUMBER_PATTERN, (match) => {
    const start = Number(fromNumbers[index]);
    index += 1;
    return String(start + (Number(match) - start) * progress);
  });
}

/**
 * Thresholds and helpers the character reads, kept out of the component file
 * so that file exports components only and stays fast-refreshable.
 */

/**
 * Loads at which another vent starts letting go.
 *
 * Three steps rather than one threshold, so the character keeps saying
 * something as the last of its capacity goes: half full vents from one place,
 * three quarters from two, and full from all three.
 */
export const WORKER_STEAM_STEPS = [0.5, 0.75, 1] as const;

/** How many vents a load opens. 0.4 opens none, 0.75 opens two, 1 opens three. */
export function workerSteamTier(load: number) {
  return WORKER_STEAM_STEPS.filter((step) => load >= step).length;
}

/**
 * A stable 0-1 phase from any identifier.
 *
 * Pass a worker's id so its rhythm is its own and does not change between
 * renders. `"8f21c4de-…"` and `"b40917aa-…"` land on visibly different offsets,
 * which is what keeps a row of characters from reading as one animation on
 * repeat.
 */
export function workerPhase(seed: string) {
  let hash = 0;

  for (let index = 0; index < seed.length; index += 1) {
    hash = (hash * 31 + seed.charCodeAt(index)) % 997;
  }

  return hash / 997;
}

