.ns-dock {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
  min-width: 0;
  background: var(--ns-surface);
}
.ns-dock-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 12px;
  flex-shrink: 0;
  border-bottom: 1px solid var(--ns-border);
}
.ns-dock-body {
  display: flex;
  flex: 1;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
}
.ns-dock-rail {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  width: 52px;
  padding: 8px 4px;
  flex-shrink: 0;
  border-inline-end: 1px solid var(--ns-border);
  overflow-y: auto;
}
.ns-dock-sidebar {
  width: 0;
  min-height: 0;
  flex-shrink: 0;
  overflow: hidden;
  transition: width 260ms cubic-bezier(0.23, 1, 0.32, 1);
}
.ns-dock-sidebar[data-open='true'] {
  width: 320px;
  border-inline-end: 1px solid var(--ns-border);
}
.ns-dock-sidebar[data-open='true'][data-size='wide'] {
  width: 400px;
}
.ns-dock-sidebar[data-open='true'][data-size='inspector'] {
  width: 416px;
}
.ns-dock-sidebar[data-size='inspector'] {
  transition-timing-function: cubic-bezier(0.32, 0.72, 0, 1);
}
.ns-dock-sidebar[data-open='true'][data-side='end'] {
  border-inline-end: 0;
  border-inline-start: 1px solid var(--ns-border);
}
.ns-dock-sheet {
  position: absolute;
  inset-inline: 0;
  bottom: 0;
  z-index: 20;
  display: flex;
  flex-direction: column;
  height: 60%;
  min-height: 0;
  overflow: auto;
  border-top: 1px solid var(--ns-border);
  background: var(--ns-surface);
  visibility: hidden;
  transform: translateY(100%);
  transition: transform 260ms cubic-bezier(0.32, 0.72, 0, 1), visibility 0s 260ms;
}
.ns-dock-sheet[data-open='true'] {
  visibility: visible;
  transform: translateY(0);
  transition-delay: 0s;
}
.ns-dock-sidebar-content {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-width: 280px;
  overflow: auto;
}
.ns-dock-main {
  position: relative;
  display: flex;
  flex-direction: column;
  flex: 1;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
}
.ns-dock-banner {
  flex-shrink: 0;
  padding: 8px;
  animation: ns-dock-banner-in 160ms ease-out;
}
@keyframes ns-dock-banner-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@media (max-width: 700px) {
  .ns-dock-sidebar[data-open='true'],
  .ns-dock-sidebar[data-open='true'][data-size='wide'] {
    width: min(320px, calc(100vw - 96px));
  }
  .ns-dock-sidebar[data-open='true'][data-size='inspector'] {
    width: min(416px, calc(100vw - 96px));
  }
}
@media (prefers-reduced-motion: reduce) {
  .ns-dock-sidebar {
    transition-duration: 120ms;
  }
  .ns-dock-banner {
    animation: none;
  }
  .ns-dock-sheet {
    transition-duration: 120ms, 0s;
    transition-delay: 0s, 120ms;
  }
  .ns-dock-sheet[data-open='true'] {
    transition-delay: 0s;
  }
}

