}
.ns-graph-canvas g[data-ns-phase='traversed'] .ns-graph-edge-comet {
  animation: ns-edge-comet var(--ns-edge-travel, 340ms) linear;
}
.ns-graph-canvas g[data-ns-instant] .ns-graph-edge-progress {
  animation: none;
}
@keyframes ns-edge-travel {
  from {
    stroke-dashoffset: 1;
  }
  to {
    stroke-dashoffset: 0;
  }
}
@keyframes ns-edge-comet {
  0% {
    stroke-dashoffset: 0;
    opacity: 0;
  }
  15% {
    opacity: 1;
  }
  85% {
    opacity: 1;
  }
  100% {
    stroke-dashoffset: -1;
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .ns-graph-canvas g[data-ns-phase] .ns-graph-edge-progress {
    animation: none;
  }
  .ns-graph-edge-comet {
    display: none;
    animation: none !important;
  }
}

.ns-graph-node-shell {
  position: relative;
  width: fit-content;
  --ns-node-accent: var(--ns-accent);
  --ns-node-tint: var(--ns-accent-soft);
  --ns-node-on-tint: var(--ns-accent);
}
.ns-graph-node-shell[data-ns-family='wait'] {
  --ns-node-accent: var(--ns-warning);
  --ns-node-tint: var(--ns-warning-soft);
  --ns-node-on-tint: var(--ns-warning);
}
.ns-graph-node-shell[data-ns-family='logic'] {
  --ns-node-accent: var(--ns-accent);
  --ns-node-tint: var(--ns-accent-soft);
  --ns-node-on-tint: var(--ns-accent);
}
.ns-graph-node-shell[data-ns-family='data'] {
  --ns-node-accent: var(--ns-success);
  --ns-node-tint: var(--ns-success-soft);
  --ns-node-on-tint: var(--ns-success);
}
.ns-graph-node-frame[data-ns-run-phase='running'] {
  border-color: var(--ns-node-accent);
}
.ns-graph-node-frame[data-ns-run-phase='idle'],
.ns-graph-node-frame[data-ns-run-phase='skipped'] {
  box-shadow: none;
}
.ns-graph-node-beam {
  position: absolute;
  z-index: 1;
  pointer-events: none;
  inset: 0;
  border-radius: inherit;
  border: 2px solid var(--ns-node-accent);
  animation: ns-node-working 1.6s ease-in-out infinite;
}
.ns-graph-node-frame[data-ns-run-phase='success']:not([data-ns-run-instant]),
.ns-graph-node-frame[data-ns-run-phase='error']:not([data-ns-run-instant]) {
  animation: ns-node-land 220ms ease-out;
}
@keyframes ns-node-working {
  0%,
  100% {
    opacity: 0.3;
  }
  50% {
    opacity: 1;
  }
}
@keyframes ns-node-land {
  from {
    transform: translateY(-2px);
  }
  to {
    transform: translateY(0);
  }
}
@media (prefers-reduced-motion: reduce) {
  .ns-graph-node-frame[data-ns-run-phase],
  .ns-graph-node-beam {
    animation: none;
  }
  .ns-graph-node-beam {
    opacity: 0.7;
  }
}

.ns-graph-canvas g[data-ns-pattern='dashed'] .ns-graph-edge-path {
  stroke-dasharray: 6 4;
}
.ns-graph-canvas g[data-ns-phase='idle'] .ns-graph-edge-arrow,
.ns-graph-canvas g[data-ns-phase='blocked'] .ns-graph-edge-arrow,
.ns-graph-canvas g[data-ns-phase='skipped'] .ns-graph-edge-arrow {
  fill: var(--ns-muted);
  opacity: 0.4;
}

.ns-graph-node-frame {
  position: relative;
}
.ns-graph-node-annotations {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

/* ---- Icon chip and method badge ---------------------------------------- */

.ns-node-kind-chip {
  position: relative;
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  flex-shrink: 0;
  border-radius: 9px;
  color: var(--ns-node-accent, var(--ns-accent));
  background: var(--ns-node-tint, var(--ns-accent-soft));
  box-shadow: inset 0 0 0 1px
    color-mix(in oklch, var(--ns-node-accent, var(--ns-accent)) 24%, transparent);
}

.ns-node-kind-icon {
  display: block;
}

.ns-node-method-badge {
  border-color: transparent;
  border-radius: 5px;
  background: var(--ns-node-tint, var(--ns-accent-soft));
  color: var(--ns-node-on-tint, var(--ns-accent));
}

/* ---- Body parts -------------------------------------------------------- */

.ns-node-code {
  border-radius: 7px;
  background: color-mix(in oklch, var(--ns-canvas) 70%, var(--ns-surface));
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--ns-border) 70%, transparent);
}

/* A `{{variable}}` is one token: the line breaks around it, never inside. */
.ns-node-code .ns-variable-chip {
  white-space: nowrap;
}

.ns-node-code-clamp {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  overflow: hidden;
  overflow-wrap: anywhere;
}

/* The fill scales along the track: `transform` keeps a value change on the
   compositor, where animating `width` re-laid the card out on every frame. */
.ns-node-meter {
  position: relative;
  height: 4px;
  overflow: hidden;
  border-radius: 999px;
  background: color-mix(in oklch, var(--ns-muted) 16%, transparent);
}

.ns-node-meter-fill {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: var(--ns-node-accent, var(--ns-accent));
  transform-origin: left center;
  transition:
    transform 520ms var(--ns-ease-out, cubic-bezier(0.16, 1, 0.3, 1)),
    background-color 240ms var(--ns-ease-out, cubic-bezier(0.16, 1, 0.3, 1));
}

.ns-node-meter[data-ns-tone='error'] .ns-node-meter-fill {
  background: var(--ns-danger);
}

.ns-node-meter[data-ns-tone='muted'] .ns-node-meter-fill {
  background: color-mix(in oklch, var(--ns-muted) 55%, transparent);
}

/* The negative delay puts a step the canvas joined late at its true position
   in the count. No fill mode: the resting value is the end of the sweep. */
.ns-node-meter-fill[data-ns-sweep] {
  transform: scaleX(1);
  animation: ns-node-meter-sweep var(--ns-sweep-ms, 1000ms) linear;
  animation-delay: var(--ns-sweep-offset, 0ms);
}

@keyframes ns-node-meter-sweep {
  from {
    transform: scaleX(0);
  }
}

.ns-node-meter-fill[data-ns-scan] {
  transform: translateX(-35%) scaleX(0.35);
  animation: ns-node-meter-scan 1.3s var(--ns-ease-in-out, cubic-bezier(0.65, 0, 0.35, 1)) infinite;
}

@keyframes ns-node-meter-scan {
  to {
    transform: translateX(100%) scaleX(0.35);
  }
}

.ns-node-pips {
  display: flex;
  gap: 3px;
}

.ns-node-pip {
  height: 6px;
  flex: 1;
  border-radius: 2px;
  background: color-mix(in oklch, var(--ns-muted) 16%, transparent);
  transition: background-color 200ms var(--ns-ease-out, cubic-bezier(0.16, 1, 0.3, 1));
  transition-delay: calc(var(--ns-item-index, 0) * 32ms);
}

.ns-node-pip[data-ns-state='used'] {
  background: color-mix(in oklch, var(--ns-node-accent, var(--ns-accent)) 45%, transparent);
}

.ns-node-pip[data-ns-state='passed'] {
  background: var(--ns-success);
}

.ns-node-pip[data-ns-state='failed'] {
  background: var(--ns-danger);
}

/* ---- Checks: a ring until the outcome lands, then a disc with its mark.
   `--i` comes from the row, so the rows land one after another. ----------- */

.ns-node-check {
  display: grid;
  place-items: center;
  width: 14px;
  height: 14px;
  flex-shrink: 0;
}

.ns-node-check svg {
  width: 14px;
  height: 14px;
  overflow: visible;
}

.ns-node-check .check-ring {
  fill: none;
  stroke: color-mix(in oklch, var(--ns-muted) 45%, transparent);
  stroke-width: 1.25;
  transition: opacity 180ms var(--ns-ease-out, cubic-bezier(0.16, 1, 0.3, 1));
  transition-delay: calc(var(--ns-item-index, 0) * 45ms);
}

.ns-node-check .check-disc {
  transform-box: fill-box;
  transform-origin: center;
  transform: scale(0.4);
  opacity: 0;
  transition:
    transform 260ms var(--ns-ease-out, cubic-bezier(0.16, 1, 0.3, 1)),
    opacity 160ms var(--ns-ease-out, cubic-bezier(0.16, 1, 0.3, 1));
  transition-delay: calc(var(--ns-item-index, 0) * 45ms);
}

.ns-node-check .check-mark {
  fill: none;
  stroke-width: 1.6;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: 1 1;
  stroke-dashoffset: 1;
  transition: stroke-dashoffset 220ms var(--ns-ease-out, cubic-bezier(0.16, 1, 0.3, 1));
  transition-delay: calc(var(--ns-item-index, 0) * 45ms + 90ms);
}

.ns-node-check .check-tick {
  stroke: var(--ns-surface);
}

.ns-node-check .check-cross {
  stroke: var(--ns-surface);
}

.ns-node-check:is([data-ns-state='passed'], [data-ns-state='failed']) .check-ring {
  opacity: 0;
}

.ns-node-check:is([data-ns-state='passed'], [data-ns-state='failed']) .check-disc {
  transform: scale(1);
  opacity: 1;
}

.ns-node-check[data-ns-state='passed'] .check-disc {
  fill: var(--ns-success);
}

.ns-node-check[data-ns-state='failed'] .check-disc {
  fill: var(--ns-danger);
}

.ns-node-check[data-ns-state='passed'] .check-tick,
.ns-node-check[data-ns-state='failed'] .check-cross {
  stroke-dashoffset: 0;
}

.ns-node-check-row {
  transition:
    background-color 220ms var(--ns-ease-out, cubic-bezier(0.16, 1, 0.3, 1)),
    color 220ms var(--ns-ease-out, cubic-bezier(0.16, 1, 0.3, 1));
  transition-delay: calc(var(--ns-item-index, 0) * 45ms);
}

/* ---- Branch cases: a port on the rail per case; the taken one fills. ---- */

.ns-node-case {
  position: relative;
  transition:
    color 220ms var(--ns-ease-out, cubic-bezier(0.16, 1, 0.3, 1)),
    background-color 220ms var(--ns-ease-out, cubic-bezier(0.16, 1, 0.3, 1));
}

.ns-node-case[data-ns-state='taken'] {
  background: var(--ns-node-tint, var(--ns-accent-soft));
  box-shadow: inset 0 0 0 1px
    color-mix(in oklch, var(--ns-node-accent, var(--ns-accent)) 30%, transparent);
}

/* Not taken: quieter, never faded — faded text drops under 4.5:1. */
.ns-node-case[data-ns-state='passed-over'] {
  color: var(--ns-muted);
}

.ns-node-case-port {
  position: absolute;
  top: calc(50% - 3.5px);
  left: -0.875rem;
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: var(--ns-surface);
  box-shadow: inset 0 0 0 1.5px var(--ns-border);
  transition:
    background-color 200ms var(--ns-ease-out, cubic-bezier(0.16, 1, 0.3, 1)),
    transform 260ms var(--ns-ease-out, cubic-bezier(0.16, 1, 0.3, 1));
}

.ns-node-case[data-ns-state='taken'] .ns-node-case-port {
  background: var(--ns-node-accent, var(--ns-accent));
  box-shadow: 0 0 0 3px
    color-mix(in oklch, var(--ns-node-accent, var(--ns-accent)) 20%, transparent);
  transform: scale(1.15);
}

/* ---- Module: a flow inside a flow, drawn as a stack that fans out while
   the child flow runs. ---------------------------------------------------- */

.ns-node-code[data-ns-variant='stack'] {
  position: relative;
  isolation: isolate;
}

.ns-node-code[data-ns-variant='stack']::before,
.ns-node-code[data-ns-variant='stack']::after {
  content: '';
  position: absolute;
  z-index: -1;
  border-radius: 8px;
  background: color-mix(in oklch, var(--ns-canvas) 55%, var(--ns-surface));
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--ns-border) 80%, transparent);
  transition: transform 420ms var(--ns-ease-out, cubic-bezier(0.16, 1, 0.3, 1));
}

.ns-node-code[data-ns-variant='stack']::before {
  inset: 3px 6px -3px;
}

.ns-node-code[data-ns-variant='stack']::after {
  inset: 6px 12px -6px;
  opacity: 0.7;
}

.ns-node-code[data-ns-variant='stack'][data-ns-active='true']::before {
  transform: translateY(2px);
}

.ns-node-code[data-ns-variant='stack'][data-ns-active='true']::after {
  transform: translateY(4px);
}

/* ---- Streaming bars ---------------------------------------------------- */

.ns-node-stream-bars {
  display: inline-flex;
  align-items: flex-end;
  gap: 2px;
  height: 10px;
}

.ns-node-stream-bars > span {
  width: 2px;
  height: 100%;
  border-radius: 1px;
  background: var(--ns-node-accent, var(--ns-accent));
  transform-origin: bottom;
  transform: scaleY(0.35);
  animation: ns-node-stream-bar 900ms var(--ns-ease-in-out, cubic-bezier(0.65, 0, 0.35, 1)) infinite
    alternate;
}

.ns-node-stream-bars > span:nth-child(2) {
  animation-delay: -300ms;
}

.ns-node-stream-bars > span:nth-child(3) {
  animation-delay: -600ms;
}

@keyframes ns-node-stream-bar {
  to {
    transform: scaleY(1);
  }
}

/* Icons expose a finite behavior, rather than product-specific node names. */
.ns-node-kind-chip[data-ns-motion='turn'] .ns-icon {
  animation: ns-node-kind-turn 1.4s linear infinite;
}
@keyframes ns-node-kind-turn {
  to {
    transform: rotate(1turn);
  }
}
.ns-node-kind-chip[data-ns-motion='tick'] .ns-icon {
  animation: ns-node-kind-tick var(--ns-poll-interval, 1000ms)
    var(--ns-ease-in-out, cubic-bezier(0.65, 0, 0.35, 1)) infinite;
}
@keyframes ns-node-kind-tick {
  0% {
    transform: rotate(0turn);
  }
  45%,
  100% {
    transform: rotate(0.5turn);
  }
}
.ns-node-kind-chip[data-ns-motion='listen']::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  box-shadow: 0 0 0 1.5px var(--ns-node-accent, var(--ns-accent));
  opacity: 0;
  pointer-events: none;
  animation: ns-node-kind-listen 1.8s var(--ns-ease-out, cubic-bezier(0.16, 1, 0.3, 1)) infinite;
}
@keyframes ns-node-kind-listen {
  0% {
    opacity: 0.7;
    transform: scale(1);
  }
  100% {
    opacity: 0;
    transform: scale(1.55);
  }
}

.ns-node-run-glyph {
  display: inline-grid;
  place-items: center;
  width: 18px;
  height: 18px;
  flex-shrink: 0;
}

.ns-node-run-glyph svg {
  width: 18px;
  height: 18px;
  overflow: visible;
}

.ns-node-run-glyph .glyph-track {
  fill: none;
  stroke: color-mix(in oklch, var(--ns-muted) 30%, transparent);
  stroke-width: 1.5;
  stroke-dasharray: 2 2.2;
  opacity: 0;
  transition: opacity 200ms var(--ns-ease-out, cubic-bezier(0.16, 1, 0.3, 1));
}

.ns-node-run-glyph .glyph-spinner {
  fill: none;
  stroke: var(--ns-accent);
  stroke-width: 1.75;
  stroke-linecap: round;
  stroke-dasharray: 0.3 1;
  transform-box: fill-box;
  transform-origin: center;
  opacity: 0;
  transition: opacity 160ms var(--ns-ease-out, cubic-bezier(0.16, 1, 0.3, 1));
}

.ns-node-run-glyph .glyph-disc {
  transform-box: fill-box;
  transform-origin: center;
  transform: scale(0.55);
  opacity: 0;
  transition:
    transform 260ms var(--ns-ease-out, cubic-bezier(0.16, 1, 0.3, 1)),
    opacity 180ms var(--ns-ease-out, cubic-bezier(0.16, 1, 0.3, 1));
}

.ns-node-run-glyph .glyph-mark {
  fill: none;
  stroke: var(--ns-surface);
  stroke-width: 1.75;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: 1 1;
  stroke-dashoffset: 1;
  transition: stroke-dashoffset 260ms var(--ns-ease-out, cubic-bezier(0.16, 1, 0.3, 1)) 110ms;
}

.ns-node-run-glyph[data-ns-phase='idle'] .glyph-track,
.ns-node-run-glyph[data-ns-phase='skipped'] .glyph-track {
  opacity: 1;
}

.ns-node-run-glyph[data-ns-phase='running'] .glyph-spinner {
  opacity: 1;
  animation: ns-node-run-spin 800ms linear infinite;
}

@keyframes ns-node-run-spin {
  to {
    transform: rotate(1turn);
  }
}

.ns-node-run-glyph[data-ns-phase='success'] .glyph-disc,
.ns-node-run-glyph[data-ns-phase='error'] .glyph-disc {
  transform: scale(1);
  opacity: 1;
}

.ns-node-run-glyph[data-ns-phase='success'] .glyph-disc {
  fill: var(--ns-success);
}

.ns-node-run-glyph[data-ns-phase='error'] .glyph-disc {
  fill: var(--ns-danger);
}

.ns-node-run-glyph[data-ns-phase='success'] .glyph-check,
.ns-node-run-glyph[data-ns-phase='error'] .glyph-cross,
.ns-node-run-glyph[data-ns-phase='skipped'] .glyph-skip {
  stroke-dashoffset: 0;
}

.ns-node-run-glyph .glyph-check {
  stroke: var(--ns-surface);
}

.ns-node-run-glyph .glyph-skip {
  stroke: var(--ns-muted);
}

/* ---- Telemetry chip hanging under a node. ------------------------------ */

.ns-node-telemetry {
  position: absolute;
  top: calc(100% + 8px);
  left: 12px;
  max-width: calc(100% - 24px);
  pointer-events: none;
  animation: ns-node-telemetry-in 220ms var(--ns-ease-out, cubic-bezier(0.16, 1, 0.3, 1));
}

@keyframes ns-node-telemetry-in {
  from {
    opacity: 0;
    transform: translateY(-4px) scale(0.98);
  }
}

.ns-node-section {
  min-width: 0;
  display: grid;
  gap: 6px;
}
.ns-node-section-heading {
  display: flex;
  min-width: 0;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  color: var(--ns-muted);
}
.ns-node-section-heading > :first-child {
  flex-shrink: 0;
  font-size: 10.5px;
  line-height: 16px;
  font-weight: 500;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.ns-node-aside {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  gap: 6px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 11px;
  line-height: 16px;
}
.ns-node-caption {
  min-width: 0;
  font-size: 11px;
  line-height: 16px;
  color: var(--ns-muted);
}
.ns-node-caption[data-ns-tone='default'] {
  color: var(--ns-text);
}
.ns-node-caption[data-ns-tone='danger'] {
  color: var(--ns-danger);
}
.ns-node-caption[data-ns-tone='success'] {
  color: var(--ns-success);
}
.ns-node-caption[data-ns-tone='warning'] {
  color: var(--ns-warning);
}
.ns-node-caption[data-ns-mono='true'] {
  font-family: ui-monospace, monospace;
}
.ns-node-caption[data-ns-truncate='true'] {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ns-node-code {
  min-width: 0;
  padding: 4px 8px;
  font-size: 11.5px;
  line-height: 18px;
}
.ns-node-code-content {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  overflow: hidden;
  overflow-wrap: anywhere;
}
.ns-node-code[data-ns-lines='1'] > .ns-node-code-content {
  -webkit-line-clamp: 1;
}
.ns-node-code[data-ns-lines='2'] > .ns-node-code-content {
  -webkit-line-clamp: 2;
}
.ns-node-code .ns-variable-text {
  font-size: inherit;
  line-height: inherit;
}
.ns-node-placeholder {
  border: 1px dashed var(--ns-border);
  border-radius: 7px;
  padding: 4px 8px;
  font-size: 11.5px;
  line-height: 18px;
  color: var(--ns-muted);
}
.ns-node-facts {
  display: flex;
  min-width: 0;
  flex-wrap: wrap;
  gap: 4px 12px;
  color: var(--ns-muted);
  font-size: 11px;
  line-height: 16px;
}
.ns-node-fact {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  gap: 4px;
}
.ns-node-fact > :last-child {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ns-node-statistic {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 8px;
}
.ns-node-statistic-value {
  display: inline-flex;
  align-items: baseline;
  gap: 4px;
  font-size: 26px;
  line-height: 1;
  font-weight: 600;
  letter-spacing: -0.025em;
}
.ns-node-statistic-value > span {
  color: var(--ns-muted);
  font-size: 14px;
  font-weight: 500;
  letter-spacing: normal;
}
.ns-node-more {
  padding: 2px 8px 0;
  color: var(--ns-muted);
  font-size: 11px;
}
.ns-node-values {
  list-style: none;
  margin: 0;
  padding: 0;
  border-radius: 7px;
  background: var(--ns-subtle);
  border: 1px solid var(--ns-border);
  overflow: hidden;
}
.ns-node-values > li {
  display: flex;
  min-width: 0;
  align-items: baseline;
  gap: 6px;
  padding: 4px 8px;
  font-size: 11.5px;
  line-height: 18px;
}
.ns-node-values > li + li {
  border-top: 1px solid var(--ns-border);
}
.ns-node-values > li > :first-child {
  max-width: 45%;
  flex-shrink: 0;
  font-family: ui-monospace, monospace;
  font-weight: 500;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
