  color: var(--ns-muted);
  text-align: end;
  user-select: none;
}
.ns-source-line-text,
.ns-source-line mark {
  white-space: pre;
}
.ns-source-line mark {
  color: var(--ns-text);
  background: transparent;
}
.ns-source-pane [data-token='key'] {
  color: var(--ns-accent);
}
.ns-source-pane [data-token='string'] {
  color: var(--ns-success);
}
.ns-source-pane [data-token='number'],
.ns-source-pane [data-token='keyword'] {
  color: var(--ns-accent);
}
.ns-source-pane [data-token='comment'],
.ns-source-pane [data-token='punctuation'] {
  color: var(--ns-muted);
}
.ns-source-pane [data-token='comment'] {
  font-style: italic;
}
.ns-variable-text[data-ns-wrap='wrap'] {
  white-space: pre-wrap;
}
.ns-variable-text[data-ns-wrap='nowrap'] {
  display: block;
  white-space: pre;
  overflow-x: auto;
}
.ns-variable-chip:focus-visible {
  outline: 2px solid var(--ns-accent);
  outline-offset: 2px;
}
.ns-control-row {
  display: flex;
  gap: var(--ns-space-sm);
  align-items: center;
  min-width: 0;
}
.ns-control-row[data-align='start'] {
  align-items: flex-start;
}
.ns-control-row > .ns-input,
.ns-control-row > .ns-select,
.ns-control-row > .ns-code-editor,
.ns-control-row > .ns-stack {
  flex: 1;
  min-width: 0;
  width: 0;
}
.ns-control-row > .ns-button,
.ns-control-row > .ns-text {
  flex: none;
}
@media (max-width: 480px) {
  .ns-control-row {
    flex-wrap: wrap;
  }
  .ns-control-row > .ns-input,
  .ns-control-row > .ns-select,
  .ns-control-row > .ns-code-editor,
  .ns-control-row > .ns-stack {
    flex-basis: 120px;
  }
}

'use client';

import { createContext, use } from 'react';
import { safeProps, type ElementProps } from './internal/props.js';

export type ColorScheme = 'light' | 'dark';
export type Brand = 'nanostack' | 'echopoint' | 'anchor';
export type Density = 'comfortable' | 'compact';
export type ThemeSettings = { colorScheme: ColorScheme; brand: Brand; density: Density };
const defaultTheme: ThemeSettings = {
  colorScheme: 'light',
  brand: 'nanostack',
  density: 'comfortable',
};
const ThemeContext = createContext<ThemeSettings>(defaultTheme);
export type ThemeProps = ElementProps<'div'> & Partial<ThemeSettings>;

export function Theme({
  colorScheme = 'light',
  brand = 'nanostack',
  density = 'comfortable',
  children,
  ...props
}: ThemeProps) {
  return (
    <ThemeContext value={{ colorScheme, brand, density }}>
      <div
        {...safeProps(props)}
        className="ns-theme"
        data-ns-theme={colorScheme}
        data-ns-brand={brand}
        data-ns-density={density}
      >
        {children}
      </div>
    </ThemeContext>
  );
}

/** Internal overlays inherit the nearest scope even when portalled to body. */
export function useThemeSettings() {
  return use(ThemeContext);
}
